SELECT 'gongkao', '适用对象', 'kp-xingce-language-cloze-real-word-target-object', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "实词辨析：适用对象"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些词只能用来形容人，有些只能形容物；有些指代大概念，有些指代小概念。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高频辨析"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "启用 vs 起用：“启用”对象通常是物（启用新印章）；“起用”对象通常是人（起用新人）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "爆发 vs 暴发：“爆发”多指力量、情绪、战争（爆发革命）；“暴发”多指突然发财、洪水（暴发户）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "扶养 vs 抚养 vs 赡养：“扶养”指平辈之间；“抚养”指长辈对晚辈；“赡养”指晚辈对长辈。"}]}]}]}]}$$ AS jsonb), NULL, '适用对象的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "适用对象"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_real_word_target_object", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
